class Solution:
    def isSquare(self, num):
        '''
        :type num: int
        :rtype: bool
        '''
        if num < 1 or num > 1000000000:
            return False

        n = len(str(num))
        if n % 2 != 0:
            return False

        for i in range(n):
            if num % 10 == 0:
                if num % 100 == 0:
                    return False
                else:
                    num //= 10
                    continue

            if num % 10 != 0:
                return False

        return True
```

