class Solution:
    def solve(self, board: List[List[str]]) -> None:
        def helper(board, start, end):
            if end >= len(board) or start >= len(board) or end < start:
                return
            if board[start][end] == "X":
                return
            if board[start][end] == "O":
                return
            for i in range(start, end + 1):
                if board[i][end] == "X":
                    return
            for j in range(start, end + 1):
                if board[start][j] == "O":
                    return
            helper(board, start + 1, end - 1)
            helper(board, start - 1, end)
            helper(board, start, end + 1)
            helper(board, start - 1, end - 1)

        helper(board, 0, len(board) - 1)

