import sys
import math


def main():
    n = int(input())
    a = int(input())
    b = int(input())
    c = int(input())

    if n == 1:
        if a == b:
            print(a)
        else:
            print(b)
    elif n == 2:
        if a == c:
            print(a)
        else:
            print(c)
    elif n == 3:
        if b == c:
            print(b)
        else:
            print(c)
    else:
        print("Invalid input")


if __name__ == "__main__":
    main()
